.mc-sidebar__brand {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: #fff;
}

.mc-sidebar__brand-sub {
  margin-top: 2px;
  font-size: 11.5px;
  color: rgba(255,255,255,0.65);
}

.mc-sidebar__section-label {
  padding: 14px 14px 6px 22px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
