.mc-sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0 14px;
  flex: 1;
}

.mc-nav-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 14px;
  border-radius: 9px;
  border-left: 3px solid transparent;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.75);
  cursor: pointer;
  background: none;
  border-top: none;
  border-right: none;
  border-bottom: none;
  width: 100%;
  text-align: left;
  transition: background-color 0.15s, color 0.15s;
  user-select: none;
}

.mc-nav-item:hover {
  background: rgba(255,255,255,0.1);
  color: #fff;
