* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; min-height: 100vh; font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif; background: #F9F9F9; }

.procesos { max-width: 1100px; margin: 0 auto; padding: 26px; }

.procesos__header { margin-bottom: 18px; }
.procesos__title { font-size: 17px; font-weight: 700; color: #1D2751; }
.procesos__subtitle { margin-top: 2px; font-size: 12px; color: #4A5568; }

.procesos__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 340px)); gap: 20px; }

.procesos__empty { text-align: center; color: #4A5568; font-size: 12px; padding: 40px 0; }

.proc-card {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 16px;
  padding: 22px 22px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: rgba(0,0,0,.1) 0px 1px 3px, rgba(0,0,0,.06) 0px 1px 2px;
}

.proc-card__top { display: flex; align-items: center; justify-content: space-between; }

.proc-card__version {
  font-size: 10px;
  font-weight: 600;
  color: #9CA3AF;
  background: #F3F4F6;
  padding: 3px 9px;
  border-radius: 999px;
}

.proc-card__name { font-weight: 700; font-size: 13px; color: #14327D; line-height: 1.3; }

.proc-card__id { font-size: 9.5px; color: #9CA3AF; font-family: monospace; margin-top: 6px; }

srcDoc.js:
appsmith.onReady(() => {
  render(appsmith.model);
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => render(m));
  }
});

function render(model) {
  const procesos = (model && model.procesos) || [];
  const grid = document.getElementById("procesos-grid");
  const empty = document.getElementById("procesos-empty");
  if (!grid || !empty) return;

  grid.innerHTML = "";

  if (procesos.length === 0) {
    empty.style.display = "block";
    return;
  }
  empty.style.display = "none";

  procesos.forEach((p) => {
    const card = document.createElement("div");
    card.className = "proc-card";

    const top = document.createElement("div");
    top.className = "proc-card__top";
    const version = document.createElement("span");
    version.className = "proc-card__version";
    version.textContent = "v" + p.version;
    top.appendChild(version);
    card.appendChild(top);

    const name = document.createElement("div");
    name.className = "proc-card__name";
    name.textContent = p.displayName || p.name;
    card.appendChild(name);

    const id = document.createElement("div");
    id.className = "proc-card__id";
    id.textContent = "ID: " + p.id;
    card.appendChild(id);

    grid.appendChild(card);
  });
}

